using System.Windows; using System.Windows.Controls; namespace CloudClient; public sealed class TransferDialog:Window { readonly PasswordBox password=new(); readonly TextBox days=new(){Text="7"}; readonly ComboBox delete=new(); readonly CheckBox download=new(){Content="Download erlauben",IsChecked=true},upload=new(){Content="Upload erlauben"}; public string Password=>password.Password; public DateTime? ExpiresUtc=>int.TryParse(days.Text,out var d)&&d>0?DateTime.UtcNow.AddDays(d):null; public bool AllowDownload=>download.IsChecked==true; public bool AllowUpload=>upload.IsChecked==true; public int AutoDeleteDays=>delete.SelectedIndex switch{1=>7,2=>14,3=>30,_=>0}; public TransferDialog(){Title="Transferlink erstellen";Width=460;Height=430;WindowStartupLocation=WindowStartupLocation.CenterOwner;ResizeMode=ResizeMode.NoResize;var p=new StackPanel{Margin=new Thickness(28)};p.Children.Add(new TextBlock{Text="Transferlink",FontSize=22,FontWeight=FontWeights.Bold,Margin=new Thickness(0,0,0,18)});Add(p,"Passwort (optional)",password);Add(p,"Gültig für Tage (0 = unbegrenzt)",days);p.Children.Add(download);p.Children.Add(upload);p.Children.Add(new TextBlock{Text="Automatisch löschen",Margin=new Thickness(0,16,0,5)});delete.Items.Add("Nie");delete.Items.Add("Nach 7 Tagen");delete.Items.Add("Nach 14 Tagen");delete.Items.Add("Nach 30 Tagen");delete.SelectedIndex=0;p.Children.Add(delete);var b=new Button{Content="Transferlink erstellen",Height=40,Margin=new Thickness(0,24,0,0)};b.Click+=(_,__)=>DialogResult=true;p.Children.Add(b);Content=p;} static void Add(Panel p,string l,Control c){p.Children.Add(new TextBlock{Text=l,Margin=new Thickness(0,8,0,5)});c.Height=34;p.Children.Add(c);} }